(()=>{
'use strict';
const $=s=>document.querySelector(s),M=window.HerstoryReportModel,E=window.HerstoryReportExport,config=window.HERSTORY_CONFIG||{},account=window.HerstoryIdentity.getProfile().userId;
const catalog=window.HERSTORY_ACTIVITY_CONFIG.activities,dialog=$('#reports-view'),scroll=$('#reports-scroll'),list=$('#report-list'),reading=$('#report-reading'),inspect=$('#report-inspect');
let feed=window.HERSTORY_REPORT_DATA||window.HERSTORY_INITIAL_STATE?.report_data||{},scheduleConfig=config.reportSchedule||{},selected=null,mode='list',detailStack=[],palette;
const frozen=new Map(),freezing=new Set(),storageIssues=new Map(),viewedKey='herstory:report-viewed:v2:'+account;let viewed={};try{viewed=JSON.parse(localStorage.getItem(viewedKey)||'{}');}catch{}
const dbReady=new Promise(resolve=>{if(!window.indexedDB)return resolve(null);const request=indexedDB.open('herstory-phase-reports-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('reports');request.onsuccess=()=>resolve(request.result);request.onerror=()=>resolve(null);});
const key=id=>account+'|'+M.CAMPAIGN+'|'+id;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;}
function button(text,fn,cls){const b=node('button',text,cls);b.type='button';b.onclick=fn;return b;}
function dateRange(p){return p.start.replaceAll('-','.')+' — '+p.end.replaceAll('-','.');}
function report(id){try{const r=M.build(id,frozen.get(id)||feed.phases?.[id],{userId:account,catalog,reportConfig:{...scheduleConfig,[id]:{...frozen.get(id)?.report_schedule,...scheduleConfig[id]}}});if(storageIssues.has(id))r.issues.push(storageIssues.get(id));return r;}catch(e){return {...M.build(id,null,{userId:account,catalog,reportConfig:scheduleConfig}),issues:[e.message]};}}
function paletteSync(){const p=window.HerstoryIdentity.getProfile().paletteId||'green';if(p!==palette){palette=p;window.stellarScene?.setPalette(p);}}
async function freeze(id){const r=report(id);if(!r.freezeEligible||(frozen.has(id)&&!storageIssues.has(id))||freezing.has(id))return;freezing.add(id);const packet=structuredClone(r.packet);packet.report_schedule={opens_at:r.status.opensAt,finalizes_at:r.status.finalizesAt};frozen.set(id,packet);try{const db=await dbReady;if(!db)throw Error('本机暂无法保存定稿，请接入服务端阶段归档');packet.snapshot.image_url=await E.imageData(packet.snapshot.image_url);for(const person of packet.people||[])if(person.avatar_url)person.avatar_url=await E.imageData(person.avatar_url);await new Promise((resolve,reject)=>{const tx=db.transaction('reports','readwrite'),req=tx.objectStore('reports').get(key(id));req.onsuccess=()=>{if(req.result)frozen.set(id,req.result);else{tx.objectStore('reports').add(packet,key(id));}};tx.oncomplete=()=>{if(!frozen.has(id))frozen.set(id,packet);resolve();};tx.onerror=()=>reject(Error('定稿存储失败，请重试同步'));});storageIssues.delete(id);}catch(e){storageIssues.set(id,e.message);}finally{freezing.delete(id);refresh(true);}}
function picture(src,alt,cls){const img=node('img',undefined,cls);img.alt=alt;img.crossOrigin='anonymous';try{img.src=E.safeSource(src);}catch{img.alt=alt+'（图片待补齐）';}img.onerror=()=>{const p=node('p','图片暂不可用，请稍后重试','report-note');img.replaceWith(p);};return img;}
function section(parent,title){const s=node('section',undefined,'report-section');s.append(node('h3',title));parent.append(s);return s;}
function note(parent,text){parent.append(node('p',text,'report-note'));}
function activityRow(parent,a){const b=button('',()=>activityDetail(a),'report-activity');b.append(node('span',a.event_date?.slice(5).replace('-','.')+' · '+M.categories[a.category].label,'report-meta'),node('strong',a.title),node('span',a.checkedAt?'打卡成功 · '+M.format(a.checkedAt):'已实际举办','report-meta'));parent.append(b);}
function peopleRow(parent,p){const row=node('div',undefined,'report-person'),b=button('',()=>personDetail(p),'report-person-button');if(p.avatar)b.append(picture(p.avatar,p.name+'的头像','report-avatar'));else b.append(node('span',Array.from(p.name)[0]||'·','report-avatar report-initial'));b.append(node('span',p.name));row.append(b);if('shared'in p){if(p.shared===null)note(row,'共同活动记录待同步');else if(!p.shared.length)note(row,'暂无共同活动记录');else for(const a of p.shared)row.append(button(a.title,()=>activityDetail(a),'report-shared'));}parent.append(row);}
function setMode(next){mode=next;list.hidden=next!=='list';reading.hidden=next!=='reading';inspect.hidden=next!=='inspect';$('#report-back').hidden=next==='list';$('#reports-sheet-title').textContent=next==='list'?'活动报告':M.phases.find(p=>p.id===selected)?.label||'活动报告';}
function detail(title,fill){detailStack.push({mode,y:scroll.scrollTop,children:mode==='inspect'?[...inspect.childNodes]:null});inspect.replaceChildren(node('h2',title));fill(inspect);setMode('inspect');scroll.scrollTop=0;$('#report-back').focus({preventScroll:true});}
function activityDetail(a){if(typeof config.openActivityDetail==='function'){const y=scroll.scrollTop;config.openActivityDetail({activityId:a.activity_id,canonicalSessionId:a.sessionId,onReturn:()=>{scroll.scrollTop=y;}});return;}detail(a.title,p=>{note(p,a.event_date+' · '+M.categories[a.category].label);note(p,a.checkedAt?'打卡成功 · '+M.format(a.checkedAt)+'（上海时间）':'已实际举办');if(a.description)p.append(node('p',a.description));});}
function personDetail(p){if(typeof config.openFriendDetail==='function'){const y=scroll.scrollTop;config.openFriendDetail({userId:p.id,onReturn:()=>{scroll.scrollTop=y;}});return;}detail(p.name,s=>{if(p.avatar)s.append(picture(p.avatar,p.name,'report-detail-avatar'));if(p.establishedAt)note(s,'建立好友关系 · '+M.format(p.establishedAt));if(p.shared===null)note(s,'共同活动记录待同步');else if(p.shared?.length){s.append(node('h3','共同活动'));p.shared.forEach(a=>{s.append(node('p',a.event_date+' · '+a.title));});}else note(s,'暂无共同活动记录');});}
function comparison(r){const w=report('week');return r.phase.id==='full'&&w.finalized&&w.snapshot&&r.finalized&&r.snapshot&&w.snapshot.view_key===r.snapshot.view_key?[w.snapshot,r.snapshot]:null;}
function renderList(){list.replaceChildren();for(const phase of M.phases){const r=report(phase.id),card=node('article',undefined,'report-entry');card.append(node('p',phase.label,'report-eyebrow'),node('h2',phase.title),node('p',dateRange(phase)),node('p',r.status.condition));if(r.status.open)card.append(button('查看'+phase.label,()=>openReport(phase.id),'report-gold'));else{if(r.status.opensAt)card.append(node('p',M.format(r.status.opensAt)+' 开放 · 上海时间','report-meta'));const lock=button('尚未开放',()=>{});lock.disabled=true;card.append(lock);}list.append(card);}}
function renderReader(){const r=report(selected),p=r.phase;reading.replaceChildren();reading.append(node('p',p.label,'report-eyebrow'),node('h1',p.title),node('p',dateRange(p),'report-dates'));if(r.snapshot)reading.append(picture(r.snapshot.image_url,p.label+'的星球留影','report-planet'));else reading.append(node('div','该阶段星球留影待补齐','report-planet report-missing'));reading.append(node('p',p.copy,'report-copy'));note(reading,r.cutoff?(r.finalized?'已定稿':'仍在更新')+' · 截至 '+M.format(r.cutoff)+'（上海时间）':'阶段记录尚未同步');if(r.ready&&!r.finalized)note(reading,p.id==='week'?'首周记录更新至 10 月 25 日结束。':'全程记录更新至结营结束，具体时间以活动配置为准。');
 const stats=node('div',undefined,'report-stats');for(const [id,c]of Object.entries(M.categories)){const b=button('',()=>detail(c.label+'活动记录',s=>{const rows=r.rows.filter(a=>a.category===id);if(!rows.length)note(s,r.counts?'暂无有效活动打卡':'活动打卡记录尚未同步');rows.forEach(a=>activityRow(s,a));}));b.style.setProperty('--category',c.color);b.append(node('span',c.label),node('strong',r.counts?String(r.counts[id]):'—'),node('small','场'));stats.append(b);}reading.append(stats);
 const totals=node('div',undefined,'report-totals');for(const [label,value,unit]of [['参与',r.counts?.participated,'场'],['发起',r.hostCount,'场'],['打卡',r.counts?.days,'天']]){const cell=node('div');cell.append(node('span',label),node('strong',value===null||value===undefined?'—':String(value)),node('small',unit));totals.append(cell);}reading.append(totals);const trail=section(reading,p.id==='full'?'两周的足迹':'活动足迹');const groups=p.id==='full'?[['第一周 · 10.19—10.25',r.rows.filter(a=>a.date<='2026-10-25')],['第二周 · 10.26—11.01',r.rows.filter(a=>a.date>='2026-10-26')]]:[['',r.rows]];for(const [title,rows]of groups){if(title)trail.append(node('h4',title));if(!rows.length)note(trail,r.counts?'这段时间暂无有效活动打卡':'活动记录尚未同步');rows.forEach(a=>activityRow(trail,a));}
 if(r.contributions.length){const c=section(reading,'我发起的活动');c.classList.add('report-contributions');note(c,'发起并举办 '+r.hostCount+' 场'+(r.partnerCount===null?'':' · 实际参与伙伴 '+r.partnerCount+' 人'));for(const a of r.contributions){activityRow(c,a);if(a.partners===null)note(c,'实际参与伙伴待同步');else a.partners.forEach(p=>peopleRow(c,p));}}
 const encounters=section(reading,p.id==='week'?'这一周的相遇':'两周的相遇');encounters.classList.add('report-encounters');if(r.friends===null||!r.ready)note(encounters,'好友记录待同步');else{const count=node('p',undefined,'report-encounter-count');count.append(node('span','新增好友 '),node('strong',String(r.friends.length)),node('span',' 位'));encounters.append(count);}if(r.companions?.length)note(encounters,'同行伙伴 '+r.companions.length+' 位');

 const pair=comparison(r);if(p.id==='full'){const s=section(reading,'星球的两次留影');reading.insertBefore(s,totals);if(pair){const grid=node('div',undefined,'report-pair');pair.forEach((shot,i)=>{const label=i?'全程结束 · 11.01':'首周结束 · 10.25',b=button('',()=>detail(label,s=>s.append(picture(shot.image_url,label,'report-zoom'))));b.append(picture(shot.image_url,label),node('span',label));grid.append(b);});s.append(grid);}else note(s,'同角度、同尺度的两次定稿留影待补齐');}
 if(r.issues.length){const s=section(reading,'记录说明');r.issues.forEach(t=>note(s,t));}const footer=node('div',undefined,'report-save'),status=node('p','','report-note');status.setAttribute('role','status');let image=null,busy=false;
 const save=button('保存星球与回顾',async()=>{if(busy)return;if(!image){prepare();return;}busy=true;save.disabled=true;status.textContent='';try{await E.saveReport(image.blob,'Herstory-'+p.label+'-'+p.end.replaceAll('-','')+'.png');}catch(e){if(e.name!=='AbortError')status.textContent='暂时无法保存，请重试。';}finally{busy=false;save.disabled=false;}},'report-gold');
 async function prepare(){if(busy||!r.snapshot)return;busy=true;save.disabled=true;save.textContent='正在生成长图…';status.textContent='';try{image=await E.exportReport(r,pair);}catch(e){status.textContent='未能生成长图：'+e.message+'。请重试。';}finally{busy=false;save.disabled=false;save.textContent=image?'保存星球与回顾':'重新生成长图';}}
 save.disabled=!r.snapshot;if(!r.snapshot)status.textContent='阶段留影补齐后可保存';footer.append(save,status);reading.append(footer);if(r.snapshot)prepare();

}
function hints(){const pending=[...M.phases].reverse().find(p=>report(p.id).status.open&&!viewed[p.id]),hint=$('#report-hint');hint.hidden=!pending;if(pending){hint.textContent=pending.label+'已开放　查看 →';hint.onclick=()=>openReport(pending.id);}}
function refresh(repaint=false){paletteSync();hints();if(mode==='list')renderList();else if(mode==='reading'&&repaint===true){const y=scroll.scrollTop;renderReader();scroll.scrollTop=y;}}
function openReport(id){if(!M.phases.some(p=>p.id===id)||!report(id).status.open)return;if(!dialog.open&&!window.HerstoryModal.open(dialog))return;selected=id;detailStack=[];setMode('reading');renderReader();scroll.scrollTop=0;viewed[id]=true;try{localStorage.setItem(viewedKey,JSON.stringify(viewed));}catch{}hints();$('#report-back').focus({preventScroll:true});}
function openSheet(){if(window.HerstoryModal.open(dialog)){selected=null;setMode('list');renderList();scroll.scrollTop=0;}}
function closeSheet(){window.HerstoryModal.close(dialog);}
function sync(data){if(data?.report_data)applyData(data.report_data);else refresh();}
function applyData(next){if(next.user_id!==account||next.campaign_id!==M.CAMPAIGN)throw Error('报告数据归属不匹配');if(Number(next.revision||0)<Number(feed.revision||0))return;feed=structuredClone(next);refresh(true);M.phases.forEach(p=>freeze(p.id));}
window.HerstoryModal.register(dialog);$('#close-reports').onclick=closeSheet;$('#report-back').onclick=()=>{if(mode==='inspect'){const previous=detailStack.pop();if(previous?.children)inspect.replaceChildren(...previous.children);setMode(previous?.mode||'reading');scroll.scrollTop=previous?.y||0;}else{selected=null;setMode('list');renderList();scroll.scrollTop=0;}};dialog.addEventListener('close',()=>{selected=null;detailStack=[];setMode('list');});
const api={openSheet,closeSheet,openReport,sync,applyData,onTab(tab){if(tab==='reports')openSheet();},configureSchedule(next){scheduleConfig=next;refresh(true);M.phases.forEach(p=>freeze(p.id));},getReport:report,getState(){return {selected,mode,account,palette,reports:Object.fromEntries(M.phases.map(p=>[p.id,{open:report(p.id).status.open,finalized:report(p.id).finalized,frozen:frozen.has(p.id)}]))};}};window.HerstoryReports=window.HerstorySharing=api;
dbReady.then(async db=>{if(db)await Promise.all(M.phases.map(p=>new Promise(resolve=>{const req=db.transaction('reports').objectStore('reports').get(key(p.id));req.onsuccess=()=>{if(req.result)frozen.set(p.id,req.result);resolve();};req.onerror=()=>resolve();})));refresh();M.phases.forEach(p=>freeze(p.id));});refresh();setInterval(refresh,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});
})();
